<script setup lang="ts">import {computed} from 'vue';import {useMarketStore} from '../../stores/market';const market=useMarketStore();const last=computed(()=>market.candles.at(-1));const period=computed(()=>market.candles.slice(-({'1H':24,'4H':6,'1D':1}[market.timeframe])));const high=computed(()=>period.value.length?Math.max(...period.value.map(x=>x.high)):0);const low=computed(()=>period.value.length?Math.min(...period.value.map(x=>x.low)):0);const volume=computed(()=>period.value.reduce((s,x)=>s+x.volume,0));const change=computed(()=>period.value.length&&last.value?((last.value.close/period.value[0]!.open-1)*100):0);const fmt=(n:number)=>n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});</script>
<template><header class="topbar"><div class="pair"><span class="coin">₿</span><strong>BTC/USDT</strong><span class="caret">⌄</span></div><div class="price-block"><strong>{{last?fmt(last.close):'—'}}</strong><span :class="change>=0?'green':'red'">{{change>=0?'+':''}}{{change.toFixed(2)}}%</span></div><div class="market-stat"><small>24h High</small><b>{{high?fmt(high):'—'}}</b></div><div class="market-stat"><small>24h Low</small><b>{{low?fmt(low):'—'}}</b></div><div class="market-stat"><small>24h Vol</small><b>{{volume?volume.toFixed(1)+' BTC':'—'}}</b></div><div class="top-spacer"/><RouterLink class="learning-chip" to="/learning"><span>✳</span> Pattern Learning</RouterLink><button class="mode-chip"><span class="live-dot"/> Demo <span>⌄</span></button></header></template>
